/**
 * ExplainableText — free text that may contain industry terminology.
 *
 * Used where Vision renders words it did not write itself: a Sprint task title
 * generated by the plan engine, an expert brief line, a Playbook row, a Next Best
 * Move reason. Any term the glossary knows becomes an explanation affordance;
 * everything else is rendered exactly as it was.
 *
 * EXACT TOKEN MATCHING — never substring (Part 5).
 *   A term is only wrapped when it appears as a whole word or whole phrase, the
 *   same rule Glossary.detectTerms uses. This is what stops "ARR" from being
 *   found inside "arrow", or "multiple" inside an ordinary sentence. The match
 *   is then looked up by EXACT alias equality, so a partial hit can never be
 *   decorated even if a future alias list is edited carelessly.
 *
 * Deterministic: it only ever wraps terms in the controlled glossary, it caps
 * how many it will decorate (Part 16 — never Wikipedia), and it skips a term the
 * session has already explained (Part 24).
 */

import React from 'react';
import ExplainWithGalileo from './ExplainWithGalileo';
import { detectTerms, hasTermBeenExplained } from '@/lib/galileo/glossary';

/** Escape an alias so it is matched literally inside the alternation. */
function escapeAlias(alias) {
  return alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export default function ExplainableText({ text, surface = null, className = '' }) {
  if (!text) return null;
  const source = String(text);

  const found = detectTerms(source).filter((entry) => !hasTermBeenExplained(entry.id));
  if (found.length === 0) return <span className={className}>{source}</span>;

  const aliases = found
    .flatMap((entry) => entry.aliases.map((alias) => ({ alias, entry })))
    .sort((a, b) => b.alias.length - a.alias.length);

  // Word-boundary phrase match: the alias must not be flanked by other letters
  // or digits. Mirrors detectTerms exactly — one rule, two call sites.
  const pattern = new RegExp(
    `(^|[^a-z0-9])(${aliases.map(({ alias }) => escapeAlias(alias)).join('|')})(?=[^a-z0-9]|$)`,
    'gi'
  );

  const nodes = [];
  let cursor = 0;
  let match;

  while ((match = pattern.exec(source)) !== null) {
    const term = match[2];
    const start = match.index + match[1].length;

    if (start > cursor) {
      nodes.push(<React.Fragment key={`t${cursor}`}>{source.slice(cursor, start)}</React.Fragment>);
    }

    const hit = aliases.find(({ alias }) => alias.toLowerCase() === term.toLowerCase());

    if (hit) {
      nodes.push(
        <ExplainWithGalileo key={`x${start}`} term={hit.entry.id} surface={surface}>
          {term}
        </ExplainWithGalileo>
      );
    } else {
      nodes.push(<React.Fragment key={`x${start}`}>{term}</React.Fragment>);
    }

    cursor = start + term.length;
    // Guard against a zero-width match ever looping forever.
    if (pattern.lastIndex <= start) pattern.lastIndex = start + 1;
  }

  if (cursor < source.length) {
    nodes.push(<React.Fragment key={`t${cursor}`}>{source.slice(cursor)}</React.Fragment>);
  }

  return <span className={className}>{nodes}</span>;
}